  'Valuacion en pesos con cotizaciones en USD al t/c BNA CYPRESS.',
  'Valuacion BYMA ARS + Instrumentos No Liquidos - USD BNA',
  'Esquema ARS - USD BNA C'
);
cy.validarEsquemaValuacionCreado(_support_constants__WEBPACK_IMPORTED_MODULE_0__["default"].VALUATION_SCHEME);

